/**
 * Report 178 («сборка + патрон… бронежилеты и их плиты»): what a boss carries and how his armour is plated, from the game's
 * bot loadouts (about fifteen per bot). Generated by scripts/bosses/boss-gear.mjs into bossGear.json; PvP and PvE list
 * the same loadouts. The Gallery shows it in «Вооружение» and «Броня» (src/gallery/BossInfoPanel.tsx).
 */
import type { RaidMode } from '../domain/types'
import type { Bilingual } from './bossInfo'
import data from './bossGear.json'
import retinueData from './bossRetinue.json'

/** [min, max] armour class; one class when three of four plates have it. */
export type ClassRange = readonly [number, number]

export interface BossGearItem { id: string; name: Bilingual }
export interface BossGearWeapon extends BossGearItem { ammo: BossGearItem[] }

export interface BossGearGroup {
  /** The maps of this kit, when the boss's kit differs by map (Black Division, The Wedge). */
  maps?: string[]
  /** This kit is on every map but the other groups' (Black Division's heavy kit). */
  elsewhere?: boolean
  weapons: BossGearWeapon[]
  /** Body armour and armoured rigs, the most worn first. */
  armor: BossGearItem[]
  /** Share of the loadouts with body armour, 0–1. */
  armored: number
  plates: { front?: ClassRange; back?: ClassRange; side?: ClassRange }
  helmet?: ClassRange
  helmetId?: string
  helmeted: number
  /** A face cover with armour (Tagilla's welding masks). */
  face?: ClassRange
  /** The retinue: helmets with armour and rigs without it, the most worn first (owner, 20.11.2026: «во что они одеты»). */
  helmets?: BossGearItem[]
  rigs?: BossGearItem[]
  /** Flashlights and lasers on the long guns: the share of guns with one, with white light, with infrared (0–1). */
  lights?: BossLights
}

export interface BossLights { share: number; white: number; ir: number; devices: BossGearItem[] }

/** «Фонарь» is named from half the guns on; the warning from three in four (report 201: Glukhar's guards, 79–100 %). */
export const LIGHTS_SHOWN = 0.5
export const LIGHTS_WARNED = 0.75
/** A kind of light counts in the warning from a quarter of the guns on. */
const LIGHT_KIND = 0.25

/**
 * What the guard's lights do to you (report 201, 20.11.2026: «Свита слепит фонарями сильно чаще других NPC»): white light blinds up
 * close, infrared only through night vision. Nothing below three guns in four.
 */
export function lightsWarning(lights: BossLights | undefined): string | undefined {
  if (!lights || lights.share < LIGHTS_WARNED) return undefined
  const white = lights.white >= LIGHT_KIND
  const ir = lights.ir >= LIGHT_KIND
  if (white && ir) return 'Почти всегда с фонарём или ИК: свет слепит вблизи, ИК — в ПНВ'
  if (white) return 'Почти всегда с фонарём: слепит вблизи'
  if (ir) return 'Почти всегда с ИК-подсветкой: слепит в ПНВ'
  return 'Почти всегда с ЛЦУ'
}

/** `guards`: all the guards' kit as one (no longer shown: «Свита» below names each kind). */
export interface BossGear { groups: BossGearGroup[]; guards?: Omit<BossGearGroup, 'maps'> }

/**
 * Ammo the players met that the bot loadouts do not list (kept here: bossGear.json is generated). Per boss, per weapon id, in
 * the kit of every map (`maps` unset) or of the kit for the other maps (`elsewhere`):
 *   - report №198 (19.11.2026): «Умирал от 7Н33 патрона лично» — Shturman's TKPD (the loadouts give SP only; Zryachiy's
 *     same carbine has 7N33 too). «Полагаю, что и FMJ» is a guess: not added.
 *   - report №195 (19.11.2026): «Встречаются 855а1 патроны и CBJ Blackout» — Black Division away from Icebreaker and the Lab
 *     (their Icebreaker / Lab kit has both).
 */
const SEEN_AMMO: Record<string, Array<{ weapon: string; ammo: BossGearItem; elsewhere?: true }>> = {
  shturman: [{ weapon: '68aee763130c00663d08aea8', ammo: { id: '68bad8376cb22acf1107a586', name: { ru: '7Н33', en: '7N33' } } }],
  'black-division': [
    { weapon: '5447a9cd4bdc2dbd208b4567', ammo: { id: '54527ac44bdc2d36668b4567', name: { ru: 'M855A1', en: 'M855A1' } }, elsewhere: true },
    { weapon: '5fbcc1d9016cce60e8341ab3', ammo: { id: '64b8725c4b75259c590fa899', name: { ru: 'CBJ', en: 'CBJ' } }, elsewhere: true },
  ],
}

function withSeenAmmo(gear: Record<string, BossGear>): Record<string, BossGear> {
  const out = { ...gear }
  for (const [boss, seen] of Object.entries(SEEN_AMMO)) {
    const known = out[boss]
    if (!known) continue
    out[boss] = {
      ...known,
      groups: known.groups.map((group) => ({
        ...group,
        weapons: group.weapons.map((weapon) => {
          const extra = seen.filter((entry) => entry.weapon === weapon.id && (entry.elsewhere ? group.elsewhere : !group.maps?.length) && !weapon.ammo.some((ammo) => ammo.id === entry.ammo.id))
          return extra.length ? { ...weapon, ammo: [...weapon.ammo, ...extra.map((entry) => entry.ammo)] } : weapon
        }),
      })),
    }
  }
  return out
}

const GEAR = withSeenAmmo(data as unknown as Record<string, BossGear>)

export function bossGear(key: string): BossGear | undefined {
  return GEAR[key]
}

/** How many of one kind of guard come with the boss on these maps. */
export interface RetinueCount { min: number; max: number; maps: string[] }
/** An item a guard may carry: the share of guards that have it, in percent (at least 1). */
export interface RetinueLoot { id: string; chance: number }
/** One kind of guard (owner, 20.11.2026: «какая свита, сколько человек, какая броня, оружие и какие у них патроны бывают»). */
export type RetinueMember = Partial<Omit<BossGearGroup, 'maps' | 'elsewhere'>> & {
  name: Bilingual
  counts: RetinueCount[]
  /** The Goons: this one's kit is on his own page. */
  ref?: string
  /** What he may have on him, the likeliest first; `lootPve` only where PvE's differs. */
  loot?: RetinueLoot[]
  lootPve?: RetinueLoot[]
}
/** `squad`: the boss walks with equals (the Goons), not guards. */
export interface BossRetinue { squad?: boolean; members: RetinueMember[] }

const RETINUE = retinueData as unknown as Record<string, BossRetinue>

/** The boss's retinue (scripts/bosses/boss-gear.mjs → bossRetinue.json), from the game's bot data. */
export function bossRetinue(key: string): BossRetinue | undefined {
  return RETINUE[key]
}

/** A guard's kit: his own loadouts, or the page he refers to. */
export function retinueGear(member: RetinueMember): Omit<BossGearGroup, 'maps'> | undefined {
  if (member.ref) return GEAR[member.ref]?.groups[0]
  return member.weapons && member.armor && member.plates ? member as Omit<BossGearGroup, 'maps'> : undefined
}

/** What a guard may carry in this mode: PvE's own list where it has one, else the PvP one (the Season's too). */
export function retinueLoot(member: RetinueMember, mode: RaidMode): RetinueLoot[] {
  return (mode === 'pve' ? member.lootPve ?? member.loot : member.loot) ?? []
}

/** The maps the whole retinue comes on: more than one, and each guard's line names them («Таможня: 2–4 · Терминал: 4»). */
export function retinueMaps(retinue: BossRetinue): string[] {
  return [...new Set(retinue.members.flatMap((member) => member.counts.flatMap((count) => count.maps)))]
}

/** [fewest, most] of one kind, or of the whole retinue, over the maps. */
export function memberSize(member: RetinueMember): ClassRange {
  return [Math.min(...member.counts.map((count) => count.min)), Math.max(...member.counts.map((count) => count.max))]
}

export function retinueSize(retinue: BossRetinue): ClassRange {
  const maps = new Set(retinue.members.flatMap((member) => member.counts.flatMap((count) => count.maps)))
  let fewest = Infinity
  let most = 0
  for (const map of maps) {
    const here = retinue.members.map((member) => member.counts.find((count) => count.maps.includes(map))).filter((count) => count !== undefined)
    fewest = Math.min(fewest, here.reduce((sum, count) => sum + count.min, 0))
    most = Math.max(most, here.reduce((sum, count) => sum + count.max, 0))
  }
  return maps.size ? [fewest, most] : [0, 0]
}

/** «6», «4–5». */
export function classLabel(range: ClassRange): string {
  return range[0] === range[1] ? String(range[0]) : `${range[0]}–${range[1]}`
}
